// Lấy text từ message
const message = $input.first().json.body.message || {};
const chatId = message.chat?.id;
const text = message.text || '';

// Tìm URL trong message (regex đơn giản)
const urlRegex = /(https?:\/\/[^\s]+)/g;
const urls = text.match(urlRegex);

return {
  chatId: chatId,
  text: text,
  urls: urls || [],
  videoUrl: urls ? urls[0] : null  // Lấy URL đầu tiên
};

// Script 2: Chunking với threshold
const segments = $input.first().json.segments;
const threshold = 60 * 4; // max seconds

let currentText = '';
let currentStart = segments[0]?.start || 0;
const chunks = [];

segments.forEach((segment, index) => {
    // Thử thêm segment mới
    const newText = currentText + segment.text + ' ';
    const interval = segment.end - currentStart
    // Nếu vượt threshold và đã có text, push chunk hiện tại
    if (interval > threshold) {
        chunks.push({
            'start': currentStart,
            'end': segments[index - 1]?.end || segment.end,
            'text': currentText.trim(),
            'chunk_index': chunks.length,
            'char_count': currentText.length
        });

        // Bắt đầu chunk mới
        currentText = segment.text + ' ';
        currentStart = segment.start;
    } else {
        currentText = newText;
    }
});

// Thêm chunk cuối cùng nếu có
if (currentText.length > 0) {
    chunks.push({
        'start': currentStart,
        'end': segments[segments.length - 1]?.end || 0,
        'text': currentText.trim(),
        'chunk_index': chunks.length,
        'char_count': currentText.length
    });
}

// Thêm metadata
const result = {
    'chunks': chunks,
    'total_chunks': chunks.length,
    'total_segments': segments.length,
    'method': 'chunking',
    'threshold': threshold
};

return result;

